    implement(listNotes, (_, { session, fail }) =>
      session
        ? [...listOf(session).filter((item) => !item.archived && item.pinned), ...listOf(session).filter((item) => !item.archived && !item.pinned)].map(shown)
        : fail('Unauthorized', {}),
    ),
    implement(getNote, ({ number }, { session, fail }) => {
      const item = /^[1-9][0-9]*$/.test(number) ? listOf(session).find((note) => note.number === Number(number)) : undefined
      return item ? { ...shown(item), archived: item.archived } : fail('NotFound', { number })
    }),
    implement(exportNotes, ({ format = 'json' }, { session, fail }) => {
      if (!session) return fail('Unauthorized', { message: 'Sign in' })
      if (format !== 'json' && format !== 'csv') return fail('UnknownFormat', { message: 'Use format json or csv' })
      const items = listOf(session)
      const notes = [...items.filter((item) => item.pinned), ...items.filter((item) => !item.pinned)].map((item) => ({
        number: item.number,
        title: item.title,
        body: item.body.replace(/\r\n?/g, '\n'),
        pinned: item.pinned,
        archived: item.archived,
        createdAt: new Date(item.createdAt).toISOString(),
      }))
      const disposition = `attachment; filename="notes-${session.user}.${format}"`
      if (format === 'json') {
        return new Response(JSON.stringify({ user: session.user, notes }), {
          headers: { 'content-type': 'application/json', 'content-disposition': disposition },
        })
      }
      const header = ['number', 'title', 'body', 'pinned', 'archived', 'createdAt']
      const rows = notes.map((n) => [String(n.number), n.title, n.body, String(n.pinned), String(n.archived), n.createdAt])
      const csv = [header, ...rows].map((row) => row.map(csvField).join(',') + '\r\n').join('')
      return new Response(csv, { headers: { 'content-type': 'text/csv; charset=utf-8', 'content-disposition': disposition } })
    }),
    implement(listArchived, (_, { session, fail }) =>
      session
        ? listOf(session)
          .filter((item) => item.archived)
          .sort((a, b) => b.createdAt.localeCompare(a.createdAt) || Number(b.id.slice(1)) - Number(a.id.slice(1)))
          .map(shown)
        : fail('Unauthorized', {}),
    ),
    implement(addNote, ({ title }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const items = ownListOf(session)
      if (!session) return fail('Invalid', { message: 'Signed out', fields: { title: 'Sign in first' } })
      const clean = title.trim()
      if (items.some((item) => item.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      const now = Date.now()
      const recent = recentAdds(session.user, now)
      if (recent.length >= ADD_LIMIT) return fail('TooMany', {})
      recent.push(now)
      const number = (numbers.get(session.user) ?? 0) + 1
      numbers.set(session.user, number)
      const item = { id: `n${++seq}`, number, title: clean, body: '', pinned: false, createdAt: new Date().toISOString(), archived: false, sharedWith: [] }
      items.unshift(item)
      changed(session)
      return shown(item)
    }),
    implement(removeNote, ({ id }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const items = ownListOf(session)
      const at = items.findIndex((item) => item.id === id)
      if (at < 0) return fail('NotFound', { id })
      if (items[at]?.archived) return fail('Archived', { id })
      const [item] = items.splice(at, 1)
      if (session && item) deleted.set(session.user, { item, at })
      return { id }
    }),
    implement(renameNote, ({ id, title }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const items = listOf(session)
      const item = items.find((note) => note.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = title.trim()
      if (items.some((note) => note.id !== id && note.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      item.title = clean
      changed(session)
      return shown(item)
    }),
    implement(saveNote, ({ id, title, body }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const items = listOf(session)
      const item = items.find((note) => note.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const cleanTitle = title.trim()
      const cleanBody = body.replace(/\r\n?/g, '\n').trim()
      const fields: { title?: string; body?: string } = {}
      if (cleanTitle.length === 0) fields.title = 'Write a title first'
      else if (cleanTitle.length > 60) fields.title = 'Use at most 60 characters'
      else if (items.some((note) => note.id !== id && note.title.toLowerCase() === cleanTitle.toLowerCase()))
        fields.title = 'You already have a note with this title'
      if (cleanBody.length > 1000) fields.body = 'Use at most 1000 characters in the body'
      if (fields.title !== undefined || fields.body !== undefined)
        return fail('Invalid', { message: fields.title ?? fields.body ?? 'Invalid', fields })
      item.title = cleanTitle
      item.body = cleanBody
      changed(session)
      return shown(item)
    }),
    implement(togglePin, ({ id }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const item = listOf(session).find((note) => note.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.pinned = !item.pinned
      changed(session)
      return shown(item)
    }),
    implement(archiveNote, ({ id }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const item = listOf(session).find((note) => note.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.archived = true
      changed(session)
      return shown(item)
    }),
    implement(restoreNote, ({ id }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const item = listOf(session).find((note) => note.id === id && note.archived)
      if (!item) return fail('NotFound', { id })
      item.archived = false
      changed(session)
      return shown(item)
    }),
    implement(removeNotes, ({ ids }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const items = ownListOf(session)
      const before = items.length
      items.splice(0, items.length, ...items.filter((item) => !ids.includes(item.id) || item.archived))
      changed(session)
      return { count: before - items.length }
    }),
    implement(archiveNotes, ({ ids }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const picked = listOf(session).filter((item) => ids.includes(item.id) && !item.archived)
      for (const item of picked) item.archived = true
      changed(session)
      return { count: picked.length }
    }),
    implement(listShared, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const shared: { id: string; title: string; owner: string }[] = []
      for (const [owner, items] of store)
        for (const item of items)
          if (owner !== session.user && !item.archived && item.sharedWith.includes(session.user))
            shared.push({ id: item.id, title: item.title, owner })
      return shared
    }),
    implement(shareNote, ({ id, name }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const item = listOf(session).find((note) => note.id === id)
      if (!session || !item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const user = name.trim().toLowerCase()
      if (user === session.user) return fail('Self', {})
      if (!item.sharedWith.includes(user)) item.sharedWith.push(user)
      changed(session)
      return shown(item)
    }),
    implement(unshareNote, ({ id, name }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const item = listOf(session).find((note) => note.id === id)
      if (!item) return fail('NotFound', { id })
      const user = name.trim().toLowerCase()
      item.sharedWith = item.sharedWith.filter((n) => n !== user)
      changed(session)
      return shown(item)
    }),
    implement(lastDeleted, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const last = deleted.get(session.user)
      return last ? { id: last.item.id, title: last.item.title } : null
    }),
    implement(undoRemove, ({ id }, { fail, session }) => {
      if (locked(session)) return fail('ReadOnly', {})
      const last = session ? deleted.get(session.user) : undefined
      if (!session || !last || last.item.id !== id) return fail('NotFound', { id })
      const items = ownListOf(session)
